client_script_on_submit.script:

function onSubmit() {
  var priority = g_form.getValue('priority');
  var priorityNum = parseInt(priority);

  // Validate priority is between 1 and 5
  if (isNaN(priorityNum) || priorityNum < 1 || priorityNum > 5) {
    g_form.addErrorMessage('Priority must be a number between 1 and 5');
    return false;
  }

  return true;
}
